// Retorna os dados do contrato
const contrato = $json.data || null;

if (!contrato) {
  return {
    encontrado: false,
    mensagem: 'Contrato não encontrado'
  };
}

return {
  encontrado: true,
  contrato_id: contrato.id,
  cliente_id: contrato.cliente_id,
  cliente_nome: contrato.cliente?.nome,
  referencia_contrato: contrato.referencia,
  descricao: contrato.descricao,
  data_inicio: contrato.data_inicio,
  data_fim: contrato.data_fim,
  quantidade_total: contrato.quantidade_total,
  quantidade_atual: contrato.quantidade_atual,
  valor_total: contrato.valor_total,
  valor_pago: contrato.valor_pago,
  saldo: contrato.valor_total - (contrato.valor_pago || 0),
  status: contrato.status,
  endereco: contrato.endereco,
  pagamentos: contrato.pagamentos || []
};
